  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, the closest analogue (Morgan 0.4268), has absolute oral bioavailability of 97% in healthy volunteers based on urinary recovery, indicating essentially complete absorption for the shared sulfonylurea-phenethyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tolbutamide, a simpler sulfonylurea, has absolute oral bioavailability of 0.85 in humans, supporting high F for the sulfonylurea class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Levosulpiride, a benzamide with a sulfonamide and similar aromatic substitution, has absolute F=23.4% in healthy Chinese volunteers; although low for a drug, it remains above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Amisulpride, a related substituted benzamide, has absolute bioavailability approximately 50% in healthy volunteers, supporting F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Avanafil, a structurally distant molecule, has F=8-10% in humans, below threshold; its low transferability limits weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F>=20%) because the closest analogue glimepiride is essentially completely bioavailable in humans, other sulfonylureas and related benzamides show F well above 20%, and even poorly absorbed close analogues such as sulpiride/levosulpiride remain at or above the 20% threshold; only a structurally distant low-F compound contradicts.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule; extrapolation relies on analogues.",
    "The closest analogue glimepiride differs in the acyl group (pyrrolinone vs chloromethoxybenzamide), which could affect transporter or metabolic behavior.",
    "No query-specific data on solubility, intestinal efflux, or first-pass metabolism are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

